  Lemma c1dA_inner : forall f s dt m1 mC r (x7 x13 x20 x21 x22 x23 x25 x26 x27 : word),
    fill_for_weight f dt (start + 8 * (s - b)) s e nb tl 0 1 sorted = Ok r ->
    Z.of_nat f = e - s + 1 -> b <= s < e -> INV m1 dt -> rw_cells asegs m1 (SPA + 288) [C8 (Z_to_bv 64 e)] ->
